 let selected=null, parent=null, hseRow=null, medicalRow=null, rows=[], showingArchive=false;
 const isAdmin=()=>role==="admin", canHse=()=>isAdmin()||role==="hse_admin", canHseRead=()=>isAdmin()||role==="hse_admin"||role==="medical_admin", canMedical=()=>role==="medical_admin", canMedicalRead=()=>isAdmin()||role==="medical_admin";
