  const conditionLibrary=window.POFRI_MEDICAL_LIBRARY||[]; $("mm-diseases").innerHTML='<div class="medical-register"><h5>سجل التاريخ المرضي والحالات الطبية – Medical Conditions Matrix <small id="mm-condition-count"></small></h5><p class="specialist-help">اختر التخصص ثم المرض ثم المستوى المطابق للوصف السريري. المستويات مرجعية وصفية وليست درجة لياقة آلية.</p><div class="medical-entry-grid"><label>التخصص الطبي<select id="mm-condition-category"><option value="">اختر التخصص</option>'+conditionLibrary.map(x=>'<option value="'+esc(x.category)+'">'+esc(x.label)+'</option>').join("")+'</select></label><label>المرض / الحالة<select id="mm-condition-disease" disabled><option value="">اختر المرض</option></select></label><label>مستوى الحالة<select id="mm-condition-level" disabled><option value="">اختر المستوى</option></select></label><label class="entry-wide">الوصف المرجعي للمستوى<textarea id="mm-condition-description" rows="2" readonly></textarea></label><label>العلاج / المتابعة<input id="mm-condition-treatment"></label><label class="entry-wide">الأثر الوظيفي<textarea id="mm-condition-impact" rows="2" placeholder="الأثر على مهام الوظيفة المحددة، إن وجد"></textarea></label></div><button type="button" class="secondary" id="mm-condition-add">إضافة الحالة الطبية</button><div id="mm-conditions-table"></div><label>ملاحظات عامة<textarea id="mm-diseases-notes" rows="2"></textarea></label></div>';
